/usr/bin/zsh -lc "cat > dev_tb.sv <<'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic [3:0] a, b, c, d, e;
    wire [3:0] q;
    logic [3:0] expected;
    logic [15:0] choices;
    integer vector_idx;
    TopModule dut (.a(a), .b(b), .c(c), .d(d), .e(e), .q(q));
    initial begin
        for (vector_idx = 0; vector_idx < 1048576; vector_idx = vector_idx + 1) begin
            {a,b,c,d,e} = vector_idx[19:0];
            choices = {d,a,e,b};
            expected = (c < 4) ? choices[c*4 +: 4] : 4'"'hf;
            #1;
            if (q "'!== expected)
                $fatal(1, "FAIL a=%h b=%h c=%h d=%h e=%h q=%h expected=%h", a,b,c,d,e,q,expected);
        end
        $display("PASS: all 1048576 binary input combinations");
        $finish;
    end
    initial begin
        #1100000;
        $fatal(1, "FAIL: simulation timeout");
    end
endmodule
EOF
timeout 30s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > compile.log 2>&1
compile_status=$?
printf '"'compile_exit_code=%s\\n' \""'$compile_status" > check_status.log
if [ "$compile_status" -eq 0 ]; then
    timeout 30s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > simulation.log 2>&1
    simulation_status=$?
    printf '"'simulation_exit_code=%s\\n' \""'$simulation_status" >> check_status.log
fi
cat compile.log simulation.log check_status.log'

